import { checkRequiredParameters } from '../../helpers/parameters/checkRequiredParameters.mjs';
import { getPairedParticipant } from '../../query/participant/getPairedParticipant.mjs';
import { deleteParticipants } from '../participants/deleteParticipants.mjs';
import { addParticipant } from '../participants/addParticipant.mjs';
import { getFlightProfile } from '../../query/event/getFlightProfile.mjs';
import { isString } from '../../tools/objects.mjs';
import { UUIDS, TOURNAMENT_RECORD, EVENT, ERROR, VALIDATE } from '../../constants/attributeConstants.mjs';
import { UNGROUPED, UNPAIRED } from '../../constants/entryStatusValues.mjs';
import { COMPETITOR } from '../../constants/participantRoleValues.mjs';
import { PAIR } from '../../constants/participantConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { DOUBLES } from '../../constants/eventConstants.mjs';
import { MISSING_PARTICIPANT_ID, INVALID_EVENT_TYPE, INVALID_PARTICIPANT_ID, INVALID_PARTICIPANT } from '../../constants/errorConditionConstants.mjs';

function modifyPairAssignment(params) {
    const paramsCheck = checkRequiredParameters(params, [
        { [EVENT]: true, [TOURNAMENT_RECORD]: true, [UUIDS]: false },
        {
            replacementIndividualParticipantId: true,
            [VALIDATE]: (value) => isString(value),
            existingIndividualParticipantId: true,
            [ERROR]: MISSING_PARTICIPANT_ID,
            participantId: true,
        },
    ]);
    const { replacementIndividualParticipantId, existingIndividualParticipantId, tournamentRecord, drawDefinition, participantId, event, uuids, } = params;
    if (paramsCheck.error)
        return paramsCheck;
    if (event?.eventType !== DOUBLES)
        return { error: INVALID_EVENT_TYPE };
    const availableIndividualParticipantIds = event?.entries
        ?.filter(({ entryStatus }) => [UNGROUPED, UNPAIRED].includes(entryStatus))
        .map(({ participantId }) => participantId) ?? [];
    if (!availableIndividualParticipantIds.includes(replacementIndividualParticipantId)) {
        return { error: INVALID_PARTICIPANT_ID };
    }
    const participant = (tournamentRecord.participants ?? []).find((participant) => participant.participantId === participantId);
    if (participant?.participantType !== PAIR)
        return { error: INVALID_PARTICIPANT, participant };
    const existingIndividualParticipantIds = participant.individualParticipantIds;
    const individualParticipantIds = [
        replacementIndividualParticipantId,
        ...existingIndividualParticipantIds.filter((individualParticipantId) => individualParticipantId !== existingIndividualParticipantId),
    ];
    const { participant: existingPairParticipant } = getPairedParticipant({
        participantIds: individualParticipantIds,
        tournamentRecord,
    });
    let newPairParticipantId;
    if (!existingPairParticipant) {
        const newPairParticipant = {
            participantId: uuids?.pop(),
            participantRole: COMPETITOR,
            individualParticipantIds,
            participantType: PAIR,
        };
        const result = addParticipant({
            participant: newPairParticipant,
            returnParticipant: true,
            tournamentRecord,
        });
        if (result.error)
            return result;
        newPairParticipantId = result.participant.participantId;
    }
    else {
        newPairParticipantId = existingPairParticipant.participantId;
    }
    const { flightProfile } = getFlightProfile({ event });
    if (drawDefinition) {
        const flight = flightProfile?.flights?.find(({ drawId }) => drawId === drawDefinition.drawId);
        if (flight) {
            flight.drawEntries = flight.drawEntries.map((entry) => entry.participantId === participantId ? { ...entry, participantId: newPairParticipantId } : entry);
        }
        drawDefinition.entries = drawDefinition.entries.map((entry) => entry.participantId === participantId ? { ...entry, participantId: newPairParticipantId } : entry);
        for (const structure of drawDefinition.structures ?? []) {
            if (structure.structures) {
                structure.positionAssignments = undefined;
                for (const subStructure of structure.structures) {
                    subStructure.positionAssignments = subStructure.positionAssignments.map((assignment) => assignment.participantId === participantId
                        ? { ...assignment, participantId: newPairParticipantId }
                        : assignment);
                }
            }
            else if (structure.positionAssignments) {
                structure.positionAssignments = structure.positionAssignments.map((assignment) => assignment.participantId === participantId
                    ? { ...assignment, participantId: newPairParticipantId }
                    : assignment);
            }
        }
    }
    event.entries = event.entries.map((entry) => (entry.participantId === participantId && {
        ...entry,
        participantId: newPairParticipantId,
    }) ||
        (entry.participantId === replacementIndividualParticipantId && {
            ...entry,
            participantId: existingIndividualParticipantId,
        }) ||
        entry);
    const participantOtherEntries = tournamentRecord.events.some(({ entries, eventId, drawDefinitions }) => {
        if (event.eventId === eventId) {
            return drawDefinitions.some(({ drawId, entries }) => drawId === drawDefinition?.drawId ? false : entries?.find((entry) => entry.participantId === participantId));
        }
        else {
            return entries?.find((entry) => entry.participantId === participantId);
        }
    });
    if (!participantOtherEntries) {
        const result = deleteParticipants({
            addIndividualParticipantsToEvents: false,
            participantIds: [participantId],
            tournamentRecord,
        });
        if (result.error)
            return result;
    }
    return { ...SUCCESS, participantOtherEntries, newPairParticipantId };
}

export { modifyPairAssignment };
